"""The two extremes and the reversal: silence, completeness, and coset separation.

This focused demonstration exhibits the three structural phenomena of the type-channel
law on explicit permutation groups, with no external dependencies:

  * PERFECT SILENCE.  For the alternating group A5 the commutator subgroup is all of A5,
    so the abelianization is trivial, the residue readout is constant, and the channel
    is exactly 0 bits — a quintic field with Galois group A5 tells an observer of
    arithmetic progressions nothing whatsoever about its factorization shapes.

  * THE CAP IS NOT THE TYPE COUNT.  For S4 the splitting types number five and carry
    2.09436 bits, yet the channel is exactly 1 bit, the cap of its C2 abelianization.

  * THE REVERSAL.  The abelian group V4 is its own abelianization, so its cap is the
    full 2 bits, yet its channel is only 0.81128 bits, because all three of its
    involutions carry the same splitting type [2,2]. The non-abelian D4 has a smaller
    relative abelianization but a readout separating its cosets far better, and its
    channel is 1.65564 bits. Richness is decided by coset separation, not abelianness.
"""

from __future__ import annotations

from itertools import permutations
from math import log2
from typing import Dict, List, Sequence, Tuple

Perm = Tuple[int, ...]


def compose(g: Perm, h: Perm) -> Perm:
    return tuple(g[h[x]] for x in range(len(g)))


def inverse(g: Perm) -> Perm:
    out = [0] * len(g)
    for x, y in enumerate(g):
        out[y] = x
    return tuple(out)


def cycle_type(g: Perm) -> Tuple[int, ...]:
    seen = [False] * len(g)
    out: List[int] = []
    for x in range(len(g)):
        if seen[x]:
            continue
        length, y = 0, x
        while not seen[y]:
            seen[y] = True
            y = g[y]
            length += 1
        out.append(length)
    return tuple(sorted(out, reverse=True))


def is_even(g: Perm) -> bool:
    return sum(length - 1 for length in cycle_type(g)) % 2 == 0


def entropy(values: Sequence[object]) -> float:
    counts: Dict[object, int] = {}
    for v in values:
        counts[v] = counts.get(v, 0) + 1
    n = len(values)
    return -sum((c / n) * log2(c / n) for c in counts.values())


def mutual_information(xs: Sequence[object], ys: Sequence[object]) -> float:
    return entropy(xs) + entropy(ys) - entropy(list(zip(xs, ys)))


def derived_subgroup(group: Sequence[Perm]) -> List[Perm]:
    identity = tuple(range(len(group[0])))
    closure = {identity}
    frontier = {compose(compose(a, b), compose(inverse(a), inverse(b)))
                for a in group for b in group}
    while frontier:
        new = set()
        for x in frontier:
            if x in closure:
                continue
            closure.add(x)
            for y in list(closure):
                for z in (compose(x, y), compose(y, x)):
                    if z not in closure:
                        new.add(z)
        frontier = new
    return sorted(closure)


def coset_index(group: Sequence[Perm], normal: Sequence[Perm]) -> Dict[Perm, int]:
    normal_set = set(normal)
    reps: List[Perm] = []
    for g in group:
        if not any(compose(g, inverse(r)) in normal_set for r in reps):
            reps.append(g)
    return {g: next(i for i, r in enumerate(reps) if compose(g, inverse(r)) in normal_set)
            for g in group}


def report(name: str, group: Sequence[Perm]) -> Tuple[float, float, float]:
    normal = derived_subgroup(group)
    idx = coset_index(group, normal)
    types = [cycle_type(g) for g in group]
    cosets = [idx[g] for g in group]
    h_t = entropy(types)
    info = mutual_information(cosets, types)
    cap = log2(len(group) // len(normal))
    determines = len({(t, c) for t, c in zip(types, cosets)}) == len(set(types))
    print(f"{name:<28} |G| = {len(group):>3}  |[G,G]| = {len(normal):>3}   "
          f"H(T) = {h_t:7.5f}   I = {info:7.5f}   cap = {cap:7.5f}   "
          f"loss = {cap - info:7.5f}   type determines coset: {determines}")
    return h_t, info, cap


def main() -> None:
    S4 = [tuple(p) for p in permutations(range(4))]
    A5 = [tuple(p) for p in permutations(range(5)) if is_even(tuple(p))]
    V4 = [g for g in S4 if cycle_type(g) in {(1, 1, 1, 1), (2, 2)}]
    D4 = [g for g in S4 if {g[0], g[2]} in ({0, 2}, {1, 3})]

    print("Structural phenomena of the type-channel law")
    print("=" * 116)
    h_s4, i_s4, cap_s4 = report("S4   (x^4 - x - 1)", S4)
    _, i_v4, cap_v4 = report("V4   (x^4 - 2x^2 + 9)", V4)
    _, i_d4, cap_d4 = report("D4   (x^4 - 2)", D4)
    _, i_a5, cap_a5 = report("A5   (perfect group)", A5)
    print("=" * 116)

    print(f"\nCAP:       S4 carries {h_s4:.5f} bits across {len({cycle_type(g) for g in S4})} "
          f"splitting types and leaks exactly {i_s4:.5f} bit "
          f"(cap {cap_s4:.5f}); over half its structure is invisible to every congruence.")
    assert abs(i_s4 - 1.0) < 1e-12 and h_s4 > 2.0

    print(f"REVERSAL:  abelian V4 gives {i_v4:.5f} bits under a {cap_v4:.1f}-bit cap, while "
          f"non-abelian D4 gives {i_d4:.5f} bits under the same {cap_d4:.1f}-bit cap.")
    assert i_v4 < i_d4

    print(f"SILENCE:   A5 is perfect, so its cap is {cap_a5:.5f} and its channel is "
          f"exactly {i_a5:.5f} bits, for every readout whatsoever.")
    assert abs(i_a5) < 1e-12 and abs(cap_a5) < 1e-12

    print("\nAll assertions passed.")


if __name__ == "__main__":
    main()

