"""Visualization: convergence of the measured channel of honest primes to the law.

For the fields x^3+x+1 (Galois group S3, law = 1 bit) and x^4-2 (Galois group D4,
law = 9/4 - (3/8)log2 3 bits), the splitting type of every unramified prime below a
growing bound is computed by distinct-degree factorization over F_p, the residue dial
is read from the maximal abelian subextension, and the running estimate of the mutual
information is plotted against the exact group-theoretic prediction.
"""

from __future__ import annotations

from math import log2
from typing import Dict, List, Optional, Sequence, Tuple

import matplotlib.pyplot as plt

L3 = log2(3.0)


def primes_up_to(n: int) -> List[int]:
    sieve = [True] * (n + 1)
    sieve[0:2] = [False, False]
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n + 1, i):
                sieve[j] = False
    return [i for i, ok in enumerate(sieve) if ok]


def poly_trim(a: List[int]) -> List[int]:
    while a and a[-1] == 0:
        a.pop()
    return a


def monic(a: List[int], p: int) -> List[int]:
    if not a:
        return a
    inv = pow(a[-1], p - 2, p)
    return [(x * inv) % p for x in a]


def poly_mod(a: List[int], f: List[int], p: int) -> List[int]:
    a = [x % p for x in a]
    df = len(f) - 1
    while a and len(a) - 1 >= df:
        c = a[-1] % p
        shift = len(a) - 1 - df
        if c:
            for i, fi in enumerate(f):
                a[shift + i] = (a[shift + i] - c * fi) % p
        a.pop()
        poly_trim(a)
    return poly_trim(a)


def poly_mulmod(a: List[int], b: List[int], f: List[int], p: int) -> List[int]:
    out = [0] * (len(a) + len(b) - 1) if a and b else []
    for i, ai in enumerate(a):
        if ai:
            for j, bj in enumerate(b):
                out[i + j] = (out[i + j] + ai * bj) % p
    return poly_mod(out, f, p)


def poly_powmod(base: List[int], e: int, f: List[int], p: int) -> List[int]:
    result, b = [1], poly_mod(list(base), f, p)
    while e:
        if e & 1:
            result = poly_mulmod(result, b, f, p)
        b = poly_mulmod(b, b, f, p)
        e >>= 1
    return result


def poly_gcd(a: List[int], b: List[int], p: int) -> List[int]:
    a, b = poly_trim([x % p for x in a]), poly_trim([x % p for x in b])
    while b:
        a = poly_mod(a, monic(b, p), p)
        a, b = b, a
    return monic(a, p) if a else a


def poly_exact_div(a: List[int], b: List[int], p: int) -> List[int]:
    a = list(a)
    q = [0] * (len(a) - len(b) + 1)
    binv = pow(b[-1], p - 2, p)
    for shift in range(len(a) - len(b), -1, -1):
        c = (a[shift + len(b) - 1] * binv) % p
        q[shift] = c
        if c:
            for i, bi in enumerate(b):
                a[shift + i] = (a[shift + i] - c * bi) % p
    return poly_trim(q)


def splitting_type(coeffs: List[int], p: int) -> Optional[Tuple[int, ...]]:
    fp = poly_trim([c % p for c in coeffs])
    if len(fp) != len(coeffs):
        return None
    fp = monic(fp, p)
    deriv = poly_trim([(i * c) % p for i, c in enumerate(fp)][1:])
    if not deriv or len(poly_gcd(fp, deriv, p)) > 1:
        return None
    shape: List[int] = []
    current, d = fp, 0
    while len(current) - 1 > 0:
        d += 1
        if 2 * d > len(current) - 1:
            shape.append(len(current) - 1)
            break
        h = poly_powmod([0, 1], p ** d, current, p)
        hx = poly_trim([(hi - (1 if i == 1 else 0)) % p
                        for i, hi in enumerate(h + [0] * max(0, 2 - len(h)))])
        g = poly_gcd(hx, current, p) if hx else list(current)
        if len(g) - 1 > 0:
            shape.extend([d] * ((len(g) - 1) // d))
            current = monic(poly_exact_div(current, g, p), p)
    return tuple(sorted(shape, reverse=True))


def entropy(values: Sequence[object]) -> float:
    counts: Dict[object, int] = {}
    for v in values:
        counts[v] = counts.get(v, 0) + 1
    n = len(values)
    return -sum((c / n) * log2(c / n) for c in counts.values())


def mutual_information(xs: Sequence[object], ys: Sequence[object]) -> float:
    return entropy(xs) + entropy(ys) - entropy(list(zip(xs, ys)))


def legendre(a: int, p: int) -> int:
    a %= p
    return 0 if a == 0 else (1 if pow(a, (p - 1) // 2, p) == 1 else -1)


def main(bound: int = 40000) -> None:
    ps = [p for p in primes_up_to(bound) if p > 3]
    experiments = [
        (r"$x^3+x+1$  ($S_3$)", [1, 1, 0, 1], lambda p: legendre(-31, p), 1.0, "#6a5cff"),
        (r"$x^4-2$  ($D_4$)", [-2, 0, 0, 0, 1], lambda p: p % 8, 9 / 4 - 3 * L3 / 8, "#00a88f"),
    ]
    fig, ax = plt.subplots(figsize=(10, 5.2))
    for label, coeffs, dial, law, color in experiments:
        types: List[Tuple[int, ...]] = []
        dials: List[int] = []
        xs: List[int] = []
        ys: List[float] = []
        for p in ps:
            t = splitting_type(coeffs, p)
            if t is None:
                continue
            types.append(t)
            dials.append(dial(p))
            if len(types) % 50 == 0 and len(types) >= 200:
                xs.append(len(types))
                ys.append(mutual_information(dials, types))
        ax.plot(xs, ys, color=color, lw=1.6, label=f"{label} measured")
        ax.axhline(law, color=color, ls="--", lw=1.2, alpha=0.85)
        ax.annotate(f"law = {law:.5f}", (xs[-1], law), textcoords="offset points",
                    xytext=(-10, 7), ha="right", color=color, fontsize=9)
    ax.set_xlabel("number of unramified primes used")
    ax.set_ylabel("measured channel (bits)")
    ax.set_title("Honest primes converge onto the group-theoretic law", fontsize=12.5)
    ax.legend(frameon=False, loc="lower right")
    ax.grid(alpha=0.25)
    ax.set_axisbelow(True)
    fig.tight_layout()
    fig.savefig("convergence.png", dpi=170)
    print("wrote convergence.png")


if __name__ == "__main__":
    main()

"""Visualization: the joint tables that make the law visible.

For each Galois group the joint census of (splitting type, abelianization coset) is
drawn as a heatmap. A row confined to a single column means the type determines the
coset — the channel is then complete. A column carrying several rows means the residue
class cannot recover the shape — the channel then sits below the splitting entropy.
"""

from __future__ import annotations

from itertools import permutations
from math import log2
from typing import Dict, List, Sequence, Tuple

import matplotlib.pyplot as plt
import numpy as np

Perm = Tuple[int, ...]


def compose(g: Perm, h: Perm) -> Perm:
    return tuple(g[h[x]] for x in range(len(g)))


def inverse(g: Perm) -> Perm:
    out = [0] * len(g)
    for x, y in enumerate(g):
        out[y] = x
    return tuple(out)


def cycle_type(g: Perm) -> Tuple[int, ...]:
    seen = [False] * len(g)
    out: List[int] = []
    for x in range(len(g)):
        if seen[x]:
            continue
        length, y = 0, x
        while not seen[y]:
            seen[y] = True
            y = g[y]
            length += 1
        out.append(length)
    return tuple(sorted(out, reverse=True))


def sign(g: Perm) -> int:
    return int(np.prod([1 if length % 2 else -1 for length in cycle_type(g)]))


def derived_subgroup(group: Sequence[Perm]) -> List[Perm]:
    identity = tuple(range(len(group[0])))
    closure = {identity}
    frontier = {compose(compose(a, b), compose(inverse(a), inverse(b)))
                for a in group for b in group}
    while frontier:
        new = set()
        for x in frontier:
            if x in closure:
                continue
            closure.add(x)
            for y in list(closure):
                for z in (compose(x, y), compose(y, x)):
                    if z not in closure:
                        new.add(z)
        frontier = new
    return sorted(closure)


def coset_index(group: Sequence[Perm], normal: Sequence[Perm]) -> Dict[Perm, int]:
    normal_set = set(normal)
    reps: List[Perm] = []
    for g in group:
        if not any(compose(g, inverse(r)) in normal_set for r in reps):
            reps.append(g)
    return {g: next(i for i, r in enumerate(reps) if compose(g, inverse(r)) in normal_set)
            for g in group}


S4 = [tuple(p) for p in permutations(range(4))]
GROUPS: List[Tuple[str, List[Perm]]] = [
    ("$S_3$  ($x^3+x+1$)", [tuple(p) for p in permutations(range(3))]),
    ("$S_4$  ($x^4-x-1$)", S4),
    ("$A_4$  ($x^4+8x+12$)", [g for g in S4 if sign(g) == 1]),
    ("$D_4$  ($x^4-2$)", [g for g in S4 if {g[0], g[2]} in ({0, 2}, {1, 3})]),
    ("$V_4$  ($x^4-2x^2+9$)", [g for g in S4 if cycle_type(g) in {(1, 1, 1, 1), (2, 2)}]),
    ("$C_4$  ($\\Phi_5$)", [g for g in S4 if g[1] == (g[0] + 1) % 4
                            and g[2] == (g[0] + 2) % 4 and g[3] == (g[0] + 3) % 4]),
]


def main() -> None:
    fig, axes = plt.subplots(2, 3, figsize=(13, 7.2))
    for ax, (name, group) in zip(axes.ravel(), GROUPS):
        normal = derived_subgroup(group)
        idx = coset_index(group, normal)
        types = sorted({cycle_type(g) for g in group}, reverse=True)
        ncos = len(set(idx.values()))
        table = np.zeros((len(types), ncos))
        for g in group:
            table[types.index(cycle_type(g)), idx[g]] += 1
        ax.imshow(table, cmap="viridis", aspect="auto")
        for i in range(len(types)):
            for j in range(ncos):
                ax.text(j, i, int(table[i, j]), ha="center", va="center",
                        color="white" if table[i, j] < table.max() * 0.6 else "black",
                        fontsize=10)
        ax.set_xticks(range(ncos))
        ax.set_xticklabels([f"class {j}" for j in range(ncos)], fontsize=8)
        ax.set_yticks(range(len(types)))
        ax.set_yticklabels(["[" + ",".join(map(str, t)) + "]" for t in types], fontsize=9)
        cap = log2(len(group) // len(normal))
        ax.set_title(f"{name}   cap $={cap:.3f}$ bits", fontsize=10.5)
    fig.suptitle("Joint census of splitting type against abelianization coset",
                 fontsize=13)
    fig.tight_layout(rect=(0, 0, 1, 0.96))
    fig.savefig("joint_tables.png", dpi=170)
    print("wrote joint_tables.png")


if __name__ == "__main__":
    main()
